/**
 * Title, description and actions at the top of a working page (`design/components/page-header.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/page-header.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, resolveSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/page-header.module.css'
import Inline from '../layout/Inline'

export interface PageHeaderProps {
  /**
   * Vocabulary controls only: one primary, and the rest less prominent.
   */
  actions?: JSX.Element
  description?: string
  title: string
  /**
   * An InlineEdit of the title, drawn beside the `<h1>`, with `title` as its `value` and
   * `size="lg"`. PageHeader hands it `valueHidden`, because the `<h1>` draws the value. The app
   * gives it its label, its handlers and, for a save that waits for a server, `editing`,
   * `pending` and `error`.
   */
  titleEdit?: JSX.Element
}

/** Title, description and actions at the top of a working page. */
export default function PageHeader(given: PageHeaderProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const actionsSlot = resolveSlot(() => props.actions)
    const titleEditSlot = resolveSlot(
      () => props.titleEdit,
      () => ({ valueHidden: true }),
    )
    return (
      <header class={styles.header} data-member="page-header">
        {/* text */}
        <div class={styles.text}>
          {titleEditSlot.filled() ? (
            <div class={styles.titleRow}>
              {/* title */}
              <h1 class={styles.title}>{props.title}</h1>
              {/* titleEdit */}
              <div class={styles.titleEdit}>{titleEditSlot()}</div>
            </div>
          ) : (
            <h1 class={styles.title}>{props.title}</h1>
          )}
          {props.description !== undefined ? (
            <p class={styles.description}>{props.description}</p>
          ) : null}
        </div>
        {actionsSlot.filled() ? (
          <Inline gap={3} wrap={true}>
            {actionsSlot()}
          </Inline>
        ) : null}
      </header>
    )
  })
}
